// NodeTlsSettings REALITY / TLS 参数，照抄 Xboard `buildNodeConfig()`。**不改名、不改类型。**
type NodeTlsSettings struct {
	// CertFile 证书全链文件在**节点上**的路径。bp-node.service 用 LoadCredential 挂载，
	// 所以是 `/run/credentials/bp-node.service/fullchain.pem`，不是 `/etc/bp/certs/…`。
	CertFile *string `json:"cert_file,omitempty"`

	// CertMode 证书来源，v2node `api/v2board/node.go` 的 `TlsSettings.CertMode`：
	// `file`（本机已有证书文件，**本项目唯一用法**）/ `none` / `dns` / `http` / `self`。
	// 🔴 `dns` / `http` / `self` 会让 v2node 自己签发或自签 —— 与 ADR 0004 §3.4「钉 Let's Encrypt」
	// 相悖，且 DynamicUser + ProtectSystem=strict 下它根本写不了盘。只用 `file`。
	// 2026-09-02 读 v2node v0.4.3 源码核实（此前契约头部标「需核实」）。
	CertMode *string `json:"cert_mode,omitempty"`

	// Dest REALITY 回落目标的**主机名，不含端口** —— 端口在 `server_port`。
	//
	// 🔴 这一条是实测定下来的，不是照抄：v2node（`core/inbound.go` 的 Reality 分支）
	// 把两者拼成 `fmt.Sprintf("%s:%s", dest, server_port)`。
	// 如果 `dest` 里已经带了端口，拼出来就是 `www.example.com:443:`，
	// xray 报 `please fill in a valid value for "target"` ——
	// **报错指向 target 字段，而真正的原因是我们多发了一个冒号**。
	// 2026-09-01 首次真机接入时实测。
	Dest *string `json:"dest,omitempty"`

	// KeyFile 私钥文件在节点上的路径，同上：`/run/credentials/bp-node.service/privkey.pem`。
	KeyFile *string `json:"key_file,omitempty"`

	// PrivateKey **REALITY x25519 私钥。** 凭据不落盘、不进仓库，来源是 Secret Manager。
	PrivateKey *string `json:"private_key,omitempty"`
	ServerName *string `json:"server_name,omitempty"`

	// ServerPort REALITY 回落目标的端口，**字符串**（v2node 的 `TlsSettings.ServerPort` 是 string）。
	// 注意它与 `NodeConfig.server_port`（节点自己的监听端口，整数）**不是一回事**，
	// 同名是 v2node 的既成事实，不改。
	ServerPort           *string                `json:"server_port,omitempty"`
	ShortId              *string                `json:"short_id,omitempty"`
	Xver                 *string                `json:"xver,omitempty"`
	AdditionalProperties map[string]interface{} `json:"-"`
}

// NodeTrafficPushRequest `{uid: [upload, download]}`。key 是用户 id 的**字符串**，value 是长度**恰为 2** 的非负整数数组，
