// ProxyConfig 浏览器扩展的代理配置（[client-products-spec §3.3 / §3.7](../docs/03-product/client-products-spec.md)）。
// 与计费无关：扩展本地的会话用量只用于显示，计费口径唯一来源是节点上报（data-model §9）。
type ProxyConfig struct {
	// ControlPlane 控制面的域名池（ADR 0010）。扩展用它更新自己的 API 备用域名列表；
	// PAC 里这些主机一律**直连** —— 控制面故障不得升级为数据面故障，反之亦然（system-design §5.3）。
	ControlPlane ProxyControlPlane `json:"control_plane"`

	// Endpoints HTTPS 代理入站端点，已按建议顺序排列。空数组 = 当前没有可用入站，扩展进「全部端点不可达」态。
	Endpoints []ProxyEndpoint `json:"endpoints"`

	// ExpiresIn 本份配置的有效秒数；到点前扩展会重新拉取（`chrome.alarms`）。凭据随配置一起轮换。
	ExpiresIn int32 `json:"expires_in"`

	// Pac 服务端预拼好的完整 PAC 脚本（`FindProxyForURL`）。候选串按用户地区打乱，**末位不含 `DIRECT`**。
	// 扩展本地有自定义列表时会自己重拼，所以此字段可省略。
	Pac *string `json:"pac,omitempty"`

	// Rules 分流规则表。方向对「来华外国人」是**默认走代理**（spec §3.4）：只有这里列出的才直连。
	// 扩展本地的 `Always route` / `Never route` 两个列表优先级高于本表；
	// 本地 / 私有地址与 `localhost` 由扩展固定直连，不在此表。
	Rules ProxyRules `json:"rules"`

	// RulesRev 分流规则版本。扩展只在版本变化时重拼 PAC，诊断报告里带它。
	RulesRev int64 `json:"rules_rev"`
}

// ProxyControlPlane 控制面的域名池（ADR 0010）。扩展用它更新自己的 API 备用域名列表；
// PAC 里这些主机一律**直连** —— 控制面故障不得升级为数据面故障，反之亦然（system-design §5.3）。
